Here’s a **menu-driven Graph program in C** using an **Adjacency Matrix** — it lets you **add edges, display the graph**, and check **connections**. Simple and clear for learning basics.  

---

### 📘 C Code — Menu-Based Graph Program
```c
#include <stdio.h>
#define MAX 10

int adj[MAX][MAX];
int n; // number of vertices

void createGraph() {
    int i, j, edges, src, dest;
    printf("Enter number of vertices: ");
    scanf("%d", &n);

    // Initialize adjacency matrix
    for (i = 0; i < n; i++)
        for (j = 0; j < n; j++)
            adj[i][j] = 0;

    printf("Enter number of edges: ");
    scanf("%d", &edges);

    for (i = 0; i < edges; i++) {
        printf("Enter edge (source destination): ");
        scanf("%d%d", &src, &dest);
        if (src >= n || dest >= n || src < 0 || dest < 0)
            printf("Invalid edge!\n");
        else {
            adj[src][dest] = 1;
            adj[dest][src] = 1; // remove this line if directed graph
        }
    }
}

void displayGraph() {
    int i, j;
    printf("\nAdjacency Matrix:\n");
    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++)
            printf("%d ", adj[i][j]);
        printf("\n");
    }
}

void addEdge() {
    int src, dest;
    printf("Enter edge to add (source destination): ");
    scanf("%d%d", &src, &dest);
    if (src >= n || dest >= n || src < 0 || dest < 0)
        printf("Invalid edge!\n");
    else {
        adj[src][dest] = 1;
        adj[dest][src] = 1;
        printf("Edge added successfully.\n");
    }
}

void checkConnection() {
    int src, dest;
    printf("Enter two vertices to check connection: ");
    scanf("%d%d", &src, &dest);
    if (adj[src][dest] == 1)
        printf("Vertices %d and %d are connected.\n", src, dest);
    else
        printf("No connection between %d and %d.\n", src, dest);
}

int main() {
    int choice;
    do {
        printf("\n--- Graph Menu ---\n");
        printf("1. Create Graph\n");
        printf("2. Display Graph\n");
        printf("3. Add Edge\n");
        printf("4. Check Connection\n");
        printf("5. Exit\n");
        printf("Enter your choice: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1: createGraph(); break;
            case 2: displayGraph(); break;
            case 3: addEdge(); break;
            case 4: checkConnection(); break;
            case 5: printf("Exiting...\n"); break;
            default: printf("Invalid choice!\n");
        }
    } while (choice != 5);

    return 0;
}
```

---

### 💡 Features
✅ Create graph using adjacency matrix  
✅ Add new edges anytime  
✅ Display graph neatly  
✅ Check if two vertices are connected  
✅ Works for up to 10 vertices (can increase MAX)

